"""Small spheres on the Sharpa collision meshes, in each link frame.

Each sphere covers a local patch of the collision mesh. Radius is the
distance from the patch center to its farthest vertex, at most about 8 mm.
Adjacent links are not paired. Only overlapping pairs are returned.
Fingertips and the thumb CMC/MCP virtual links have no collision mesh.
"""

import importlib.util
from pathlib import Path

import numpy as np

_tangent_path = Path(__file__).with_name("tangent_turn_step.py")
_tangent = importlib.util.spec_from_file_location("tangent_turn_step", _tangent_path)
_turn = importlib.util.module_from_spec(_tangent)
_tangent.loader.exec_module(_turn)
quat_xyzw_to_matrix = _turn.quat_xyzw_to_matrix

