def _skew(vector):
    x, y, z = (float(v) for v in vector)
    return np.array([[0.0, -z, y], [z, 0.0, -x], [-y, x, 0.0]], dtype=np.float64)


def _rotation(quat_xyzw):
    return quat_xyzw_to_matrix(quat_xyzw)


def watch_pairs(names, origins, quats_xyzw, jac_lin, jac_ang, watch_distance):
    """Overlapping sphere pairs. A positive gap adds no pair.

    Body quaternions are xyzw. watch_distance is unused; overlap is gap <= 0.
    Same-link spheres and adjacent links are omitted.
    """
    del watch_distance
    names = list(names)
    origins = np.asarray(origins, dtype=np.float64)
    quats = np.asarray(quats_xyzw, dtype=np.float64)
    jac_lin = np.asarray(jac_lin, dtype=np.float64)
    jac_ang = np.asarray(jac_ang, dtype=np.float64)
    centers = []
    jacobians = []
    radii = []
    kept = []
    for index, name in enumerate(names):
        patches = SPHERES.get(name)
        if not patches:
            continue
        rotation = _rotation(quats[index])
        for local, radius in patches:
            offset = rotation @ np.asarray(local, dtype=np.float64)
            centers.append(origins[index] + offset)
            jacobians.append(jac_lin[index] - _skew(offset) @ jac_ang[index])
            radii.append(float(radius))
            kept.append(name)
    pairs = []
    for i in range(len(kept)):
        for j in range(i + 1, len(kept)):
            if kept[i] == kept[j] or frozenset((kept[i], kept[j])) in ADJACENT:
                continue
            delta = centers[j] - centers[i]
            span = float(np.linalg.norm(delta))
            if span < 1e-8:
                continue
            gap = span - radii[i] - radii[j]
            if gap > 0.0:
                continue
            pairs.append((delta / span, jacobians[i], jacobians[j], gap, kept[i], kept[j]))
    return pairs


def _check():
    spheres = {
        "a": [(np.array([0.0, 0.0, 0.0]), 0.01)],
        "b": [(np.array([0.0, 0.0, 0.0]), 0.01)],
        "c": [(np.array([0.0, 0.0, 0.0]), 0.01)],
    }
    saved = dict(SPHERES)
    SPHERES.clear()
    SPHERES.update(spheres)
    try:
        names = ["a", "b"]
        origins = np.array([[0.0, 0.0, 0.0], [0.015, 0.0, 0.0]])
        quats = np.tile(np.array([0.0, 0.0, 0.0, 1.0]), (2, 1))
        eye = np.zeros((2, 3, 3))
        eye[0] = np.eye(3)
        eye[1] = np.eye(3)
        ang = np.zeros_like(eye)
        close = watch_pairs(names, origins, quats, eye, ang, 0.0)
        assert len(close) == 1
        assert close[0][3] < 0.0
        assert np.allclose(close[0][0], [1.0, 0.0, 0.0], atol=1e-6)
        far = origins.copy()
        far[1, 0] = 0.03
        assert watch_pairs(names, far, quats, eye, ang, 0.0) == []
        adjacent_names = ["right_index_DP", "right_index_elastomer"]
        SPHERES["right_index_DP"] = spheres["a"]
        SPHERES["right_index_elastomer"] = spheres["b"]
        adj_origins = np.zeros((2, 3))
        adj_quats = np.tile(np.array([0.0, 0.0, 0.0, 1.0]), (2, 1))
        assert watch_pairs(adjacent_names, adj_origins, adj_quats, eye, ang, 0.0) == []
    finally:
        SPHERES.clear()
        SPHERES.update(saved)
    assert len(SPHERES["right_hand_C_MC"]) > 20
    print("link_spheres ok", flush=True)


if __name__ == "__main__":
    _check()
